INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'signal', 'v./n.', '/ˈsɪɡnəl/', '示意;发信号;信号', 'I signalled to the seller that I could not wait any longer.', '我向卖家示意我不能再等了。', 'Language and Culture', 1, 0, 'senior', 'wordlist', 'required1', 'U2', 'signal to sb', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'wrist', 'n.', '/rɪst/', '手腕', 'She pointed at her wrist to show that she was in a hurry.', '她指了指手腕,表示自己赶时间。', 'Language and Culture', 2, 0, 'senior', 'wordlist', 'required1', 'U2', 'point at one''s wrist', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'obviously', 'adv.', '/ˈɒbviəsli/', '显然;明显地', 'He was obviously confused by the foreign gesture.', '他显然被这个外国手势弄糊涂了。', 'Language and Culture', 3, 0, 'senior', 'wordlist', 'required1', 'U2', 'obviously confused', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fault', 'n.', '/fɔːlt/', '责任;过错;过失', 'The misunderstanding really wasn''t my fault.', '这个误会真的不是我的错。', 'Language and Culture', 4, 0, 'senior', 'wordlist', 'required1', 'U2', 'not my fault', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'memory', 'n.', '/ˈmeməri/', '回忆;记忆', 'The strange experience slowly faded from my memory.', '那段奇怪的经历慢慢从我记忆中淡去。', 'Language and Culture', 5, 0, 'senior', 'wordlist', 'required1', 'U2', 'fade from memory', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fluency', 'n.', '/ˈfluːənsi/', '流利;流畅', 'Understanding the word took not fluency in the language, but fluency in the culture.', '理解这个词靠的不是语言的流利,而是文化的熟稔。', 'Language and Culture', 6, 0, 'senior', 'wordlist', 'required1', 'U2', 'fluency in the culture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'literally', 'adv.', '/ˈlɪtərəli/', '照字面地;字面上', 'This word should almost never be taken literally.', '这个词几乎从不能按字面意思理解。', 'Language and Culture', 7, 0, 'senior', 'wordlist', 'required1', 'U2', 'take sth literally', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'context', 'n.', '/ˈkɒntekst/', '上下文;语境', 'The meaning of the word changes greatly with the context.', '这个词的意思随语境变化很大。', 'Language and Culture', 8, 0, 'senior', 'wordlist', 'required1', 'U2', 'depend on the context', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'within', 'prep.', '/wɪˈðɪn/', '在……之内;不超过', '"Ahorita" could mean within five years or even never.', '"Ahorita"可能指五年之内,甚至永远不。', 'Language and Culture', 9, 0, 'senior', 'wordlist', 'required1', 'U2', 'within five years', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'attitude', 'n.', '/ˈætɪtjuːd/', '态度;看法', 'Since I moved abroad, my attitude towards time has changed.', '自从我搬到国外,我对时间的态度就变了。', 'Language and Culture', 10, 0, 'senior', 'wordlist', 'required1', 'U2', 'attitude towards time', '美音 /ˈætɪtuːd/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'dramatically', 'adv.', '/drəˈmætɪkli/', '显著地;剧烈地', 'My idea of being on time has changed dramatically.', '我对守时的看法发生了显著的变化。', 'Language and Culture', 11, 0, 'senior', 'wordlist', 'required1', 'U2', 'change dramatically', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'appointment', 'n.', '/əˈpɔɪntmənt/', '约会;预约', 'I am generally still on time for my appointments.', '我赴约通常还是很准时的。', 'Language and Culture', 12, 0, 'senior', 'wordlist', 'required1', 'U2', 'on time for appointments', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'panic', 'v./n.', '/ˈpænɪk/', '(使)惊慌;惊慌失措', 'When I am a little late now, I don''t panic.', '现在我稍微迟到时,也不会惊慌。', 'Language and Culture', 13, 0, 'senior', 'wordlist', 'required1', 'U2', 'don''t panic', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fry', 'n./v.', '/fraɪ/', '炸薯条;油炸', 'I couldn''t imagine what "French fries" were.', '我想象不出"French fries"是什么。', 'Language and Culture', 14, 0, 'senior', 'wordlist', 'required1', 'U2', 'French fries', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cheese', 'n.', '/tʃiːz/', '奶酪', 'Was it something fried, like snails or cheese?', '那是炸出来的东西吗,比如蜗牛或奶酪?', 'Language and Culture', 15, 0, 'senior', 'wordlist', 'required1', 'U2', 'a piece of cheese', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'amazed', 'adj.', '/əˈmeɪzd/', '大为惊奇的;吃惊的', 'She was amazed that I had never tried French fries.', '她很惊讶我从没吃过炸薯条。', 'Language and Culture', 16, 0, 'senior', 'wordlist', 'required1', 'U2', 'be amazed that', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'plate', 'n.', '/pleɪt/', '盘子;碟子', 'The waiter brought us a plate of chips.', '服务员给我们端来一盘薯条。', 'Language and Culture', 17, 0, 'senior', 'wordlist', 'required1', 'U2', 'a plate of chips', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'salty', 'adj.', '/ˈsɔːlti/', '含盐的;咸的', 'In England, gravy is a salty, meat-based sauce.', '在英国,gravy 是一种咸的、以肉为主的调味汁。', 'Language and Culture', 18, 0, 'senior', 'wordlist', 'required1', 'U2', 'a salty sauce', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'snack', 'n.', '/snæk/', '点心;小吃', 'In America, "biscuits" can mean savoury snacks.', '在美国,"biscuits"可能指咸味小吃。', 'Language and Culture', 19, 0, 'senior', 'wordlist', 'required1', 'U2', 'savoury snacks', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'embarrassed', 'adj.', '/ɪmˈbærəst/', '尴尬的;窘迫的', 'I felt embarrassed when a stranger said she liked my "pants".', '一个陌生人说喜欢我的"pants"时,我感到很尴尬。', 'Language and Culture', 20, 0, 'senior', 'wordlist', 'required1', 'U2', 'feel embarrassed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'likely', 'adj.', '/ˈlaɪkli/', '可能的;预料的', 'There are likely to be many differences in the same language.', '同一种语言里很可能存在许多差异。', 'Language and Culture', 21, 0, 'senior', 'wordlist', 'required1', 'U2', 'be likely to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'vocabulary', 'n.', '/vəˈkæbjələri/', '词汇;词汇量', 'The two kinds of English differ not just in vocabulary but also in spelling.', '这两种英语不仅在词汇上不同,在拼写上也不同。', 'Language and Culture', 22, 0, 'senior', 'wordlist', 'required1', 'U2', 'differences in vocabulary', '美音 /voʊˈkæbjəleri/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'culture', 'n.', '/ˈkʌltʃə(r)/', '文化', 'A confusing word often points to a difference in culture.', '一个令人困惑的词常常指向文化上的差异。', 'Language and Culture', 23, 0, 'senior', 'wordlist', 'required1', 'U2', 'language and culture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'language', 'n.', '/ˈlæŋɡwɪdʒ/', '语言', 'The same language may be spoken in different ways in different countries.', '同一种语言在不同国家可能有不同的说法。', 'Language and Culture', 24, 0, 'senior', 'wordlist', 'required1', 'U2', 'a foreign language', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'confusion', 'n.', '/kənˈfjuːʒn/', '困惑;混乱', 'His face showed a mix of confusion and surprise.', '他脸上混合着困惑与惊讶。', 'Language and Culture', 25, 0, 'senior', 'wordlist', 'required1', 'U2', 'a look of confusion', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'confusing', 'adj.', '/kənˈfjuːzɪŋ/', '令人困惑的', '"Ahorita" is a confusing word for many foreigners in Mexico.', '对许多在墨西哥的外国人来说,"ahorita"是个令人困惑的词。', 'Language and Culture', 26, 0, 'senior', 'wordlist', 'required1', 'U2', 'a confusing word', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'polite', 'adj.', '/pəˈlaɪt/', '礼貌的;客气的', 'It is even used as a polite way of saying "no, thanks".', '它甚至被用作礼貌地说"不,谢谢"的方式。', 'Language and Culture', 27, 0, 'senior', 'wordlist', 'required1', 'U2', 'a polite way', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'impolite', 'adj.', '/ˌɪmpəˈlaɪt/', '不礼貌的;无礼的', 'I felt it was impolite to walk away without a word.', '我觉得一句话不说就走开很不礼貌。', 'Language and Culture', 28, 0, 'senior', 'wordlist', 'required1', 'U2', 'feel impolite', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'translate', 'v.', '/trænzˈleɪt/', '翻译;转化为', 'The word can be directly translated as "right now".', '这个词可以直接翻译成"现在"。', 'Language and Culture', 29, 0, 'senior', 'wordlist', 'required1', 'U2', 'translate into', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'translation', 'n.', '/trænzˈleɪʃn/', '翻译;译文', 'The literal translation of the phrase is "I am your slave".', '这个短语的字面译文是"我是你的奴隶"。', 'Language and Culture', 30, 0, 'senior', 'wordlist', 'required1', 'U2', 'a literal translation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gesture', 'n.', '/ˈdʒestʃə(r)/', '手势;姿态', 'The same gesture may carry different meanings in different cultures.', '同样的手势在不同文化中可能含义不同。', 'Language and Culture', 31, 0, 'senior', 'wordlist', 'required1', 'U2', 'a friendly gesture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'express', 'v.', '/ɪkˈspres/', '表达;表示', 'People in some countries use their hands to express feelings.', '在一些国家,人们用手来表达感受。', 'Language and Culture', 32, 0, 'senior', 'wordlist', 'required1', 'U2', 'express feelings', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'disagreement', 'n.', '/ˌdɪsəˈɡriːmənt/', '不同意;分歧', 'Different gestures are used to show disagreement.', '人们用不同的手势来表示不同意。', 'Language and Culture', 33, 0, 'senior', 'wordlist', 'required1', 'U2', 'show disagreement', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pronunciation', 'n.', '/prəˌnʌnsiˈeɪʃn/', '发音', 'The two kinds of English also differ in pronunciation.', '这两种英语在发音上也有差异。', 'Language and Culture', 34, 0, 'senior', 'wordlist', 'required1', 'U2', 'differences in pronunciation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'spelling', 'n.', '/ˈspelɪŋ/', '拼写;拼法', 'British and American English use different spelling for some words.', '英式和美式英语对某些词用不同的拼写。', 'Language and Culture', 35, 0, 'senior', 'wordlist', 'required1', 'U2', 'differences in spelling', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stranger', 'n.', '/ˈstreɪndʒə(r)/', '陌生人', 'A stranger told me she liked my "pants".', '一个陌生人告诉我她喜欢我的"pants"。', 'Language and Culture', 36, 0, 'senior', 'wordlist', 'required1', 'U2', 'a friendly stranger', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'foreigner', 'n.', '/ˈfɒrənə(r)/', '外国人', 'The word often confuses a foreigner who speaks fluent Spanish.', '这个词常常让说一口流利西班牙语的外国人困惑。', 'Language and Culture', 37, 0, 'senior', 'wordlist', 'required1', 'U2', 'a confused foreigner', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'order', 'v./n.', '/ˈɔːdə(r)/', '点(餐);命令;顺序', 'My friend asked me if I wanted to order French fries.', '我朋友问我想不想点炸薯条。', 'Language and Culture', 38, 0, 'senior', 'wordlist', 'required1', 'U2', 'order a dish', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'menu', 'n.', '/ˈmenjuː/', '菜单', 'I saw an "eggplant" pizza on the menu and felt confused.', '我在菜单上看到"eggplant"披萨,感到很困惑。', 'Language and Culture', 39, 0, 'senior', 'wordlist', 'required1', 'U2', 'on the menu', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'imagine', 'v.', '/ɪˈmædʒɪn/', '想象;设想', 'I couldn''t imagine what an "eggplant" could be.', '我想象不出"eggplant"会是什么。', 'Language and Culture', 40, 0, 'senior', 'wordlist', 'required1', 'U2', 'imagine what', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'discover', 'v.', '/dɪˈskʌvə(r)/', '发现;发觉', 'I later discovered that understanding the word took a fluency in the culture.', '我后来发现,理解这个词需要的是对文化的熟悉。', 'Language and Culture', 41, 0, 'senior', 'wordlist', 'required1', 'U2', 'discover that', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'realise', 'v.', '/ˈriːəlaɪz/', '意识到;认识到', 'I later realised that "biscuits" in America are savoury snacks.', '我后来意识到,美国的"biscuits"是咸味小吃。', 'Language and Culture', 42, 0, 'senior', 'wordlist', 'required1', 'U2', 'realise that', '美式拼 realize;美音 /ˈriːəlaɪz/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'difference', 'n.', '/ˈdɪfrəns/', '差异;区别', 'Cultural differences in languages caused the confusion.', '语言中的文化差异造成了这种困惑。', 'Language and Culture', 43, 0, 'senior', 'wordlist', 'required1', 'U2', 'cultural differences', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reflection', 'n.', '/rɪˈflekʃn/', '反映;反射;沉思', '"Ahorita Time" is a reflection of different understandings of time.', '"Ahorita Time"反映了人们对时间的不同理解。', 'Language and Culture', 44, 0, 'senior', 'wordlist', 'required1', 'U2', 'a reflection of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'variety', 'n.', '/vəˈraɪəti/', '变体;种类;多样', 'There are many varieties of English throughout the world.', '世界各地有许多种英语变体。', 'Language and Culture', 45, 0, 'senior', 'wordlist', 'required1', 'U2', 'varieties of English', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'refuse', 'v.', '/rɪˈfjuːz/', '拒绝', 'The word can be a polite way to refuse an offer.', '这个词可以是礼貌地拒绝邀约的方式。', 'Language and Culture', 46, 0, 'senior', 'wordlist', 'required1', 'U2', 'refuse an offer', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s1u2.01', '①主谓 SV(不及物动词)/ 主谓宾 SVO(及物动词+宾语)', 'A2', 10, '上外必修一 U2 — 判断动词是否需要宾语:及物动词后必须带宾语(speak Spanish),不及物动词后不带宾语(its meaning changed)。空格选能让句子主干成立、搭配地道的动词或宾语。', 1, 'required1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s1u2.02', '②主系表 SVC(系动词后用形容词作表语)/ There be 存在句', 'A2', 10, '上外必修一 U2 — 系动词(be/look/feel/become/seem/sound/get)后接形容词作表语,不接副词;There be 表''存在/有'',后接名词。空格选系动词后正确的形容词,或存在句的正确结构。', 2, 'required1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s1u2.03', '③主谓双宾 SVOO(give sb sth)/ 主谓宾补 SVOC(make us happy / call it…)', 'A2', 10, '上外必修一 U2 — 双宾结构间接宾语在前直接宾语在后(give him a signal),或用 to/for 改写;宾补结构补足宾语(make the answer puzzling / call this eggplant)。空格选正确的语序或宾语补足语形式。', 3, 'required1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'The meaning of the word ____ greatly with the context.', 'changes', 'change', 'changing', 'to change', 'A', '主谓结构,主语 meaning 第三人称单数,谓语用 changes。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'At first the foreigner ____ fluent Spanish but still felt confused.', 'talked', 'spoke', 'said', 'told', 'B', '及物动词+宾语 Spanish,speak a language 才地道,talk/say/tell 搭配不对。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'After waiting too long, she finally ____ for the nearest bus.', 'rushed quickly', 'did a run', 'made a rush', 'went a hurry', 'C', 'make a rush for 是地道搭配,构成主谓宾;其余搭配不成立。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'The strange experience slowly ____ from my memory.', 'removed', 'deleted', 'erased', 'faded', 'D', 'fade 为不及物动词,fade from memory(逐渐消逝),构成主谓;其余多为及物且搭配不当。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'I ____ to the seller that I could not wait any longer.', 'signalled', 'spoke', 'told', 'talked', 'A', 'signal to sb 示意,构成主谓;told 需直接宾语 sb,spoke/talked 搭配不当。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'She ____ a portion of French fries for us to share.', 'asked', 'ordered', 'wished', 'hoped', 'B', '及物动词 order+宾语 a portion,构成主谓宾;其余搭配不对。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'When native speakers talk fast, I can ____ only a few words.', 'listen', 'hear of', 'catch', 'look', 'C', 'catch+宾语 a few words(听清),主谓宾;listen 不及物需 to,look 也不及物。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'My attitude towards time ____ a lot since I moved abroad.', 'has been changed', 'changes it', 'has changing', 'has changed', 'D', 'change 此处不及物表''变化'',主谓结构,用现在完成 has changed;被动 has been changed 语义不通。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'The waiter ____ us a plate of chips, not French fries.', 'brought', 'came', 'arrived', 'appeared', 'A', 'bring 及物可带宾语,构成主谓宾(后又接双宾);come/arrive/appear 不及物,不能直接带宾语。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'Gestures ____ from country to country in expressing ideas.', 'different', 'differ', 'difference', 'differently', 'B', '需要谓语动词,differ from(不同于)为不及物动词,主谓结构;其余为形容词/名词/副词。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'He laughed and ____ to the aubergines on the pizza.', 'showed', 'watched', 'pointed', 'saw', 'C', 'point to/at 指向,不及物需介词,搭配地道;show/watch/see 为及物且语义不合。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'Part of the excitement of learning a language ____ discovering the differences.', 'lies on', 'stays at', 'puts in', 'lies in', 'D', 'lie in(在于)是地道搭配,主谓;其余介词搭配错误。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'I couldn''t ____ what "French fries" really were.', 'imagine', 'think', 'guess of', 'dream', 'A', 'imagine+宾语从句,及物,主谓宾;think 后多需 about/of,guess of 不成立。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'People in some countries ____ their hands to show their feelings.', 'do', 'use', 'make', 'play', 'B', 'use+宾语 their hands,及物,主谓宾;其余搭配不地道。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'When the visitor said this, the meaning ____ completely in Chinese culture.', 'changed it', 'was changing it', 'changed', 'changed them', 'C', '此处 change 不及物表''改变'',主谓;加宾语 it/them 多余且无指代对象。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'The two kinds of English ____ in spelling, grammar and pronunciation.', 'compare', 'match', 'equal', 'differ', 'D', 'differ in(在……方面不同),不及物,主谓;compare/match/equal 为及物且语义相反。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'A few short words often ____ enough between close friends.', 'are', 'have', 'do', 'make', 'A', '此处需系动词构成判断;但本题考主语+谓语成立,are 让主干完整;have/do/make 缺宾语或语义不通。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'She ____ at her wrist to show that time was running out.', 'looked', 'pointed', 'watched', 'saw', 'B', 'point at 指向,主谓(带介词短语);look 需 at 但 look at one''s wrist 语义不如 point 自然,且其余为及物。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'My dad ____ this pizza, and it was covered in aubergines.', 'asked', 'requested for', 'ordered', 'wished', 'C', 'order+宾语 this pizza,及物,主谓宾;request 后不接 for,ask/wish 语义不合。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.01'), 'The host smiled and ____, "Where? Where?"', 'spoke', 'talked', 'told', 'said', 'D', 'say+引语,及物,主谓宾;speak/talk 不及物不能直接接引语,tell 需 sb。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'His face was ____ when he saw the foreign gesture.', 'confused', 'confusedly', 'confuse', 'confusing him', 'A', '系动词 was 后用形容词作表语,confused(感到困惑的);副词 confusedly 不能作表语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'Waiting longer wasn''t ____, but I felt I should stay.', 'pleasantly', 'pleasant', 'please', 'pleasure', 'B', '系动词 wasn''t 后接形容词 pleasant 作表语;副词/动词/名词都不行。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'This idea sounded very ____ to me, because in England biscuits are sweet.', 'strangely', 'stranger ', 'strange', 'strangeness', 'C', 'sound 为系动词,后接形容词 strange 作表语;副词 strangely 不能作表语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), '____ a time when she really wanted to walk away.', 'It was', 'There had', 'It had', 'There was', 'D', 'There be 存在句表''有/存在''某段时间;It was 无法引出 a time when 的存在含义。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'After moving abroad, I no longer feel ____ about being a little late.', 'anxious', 'anxiously', 'anxiety', 'anxiousness', 'A', 'feel 为系动词,后接形容词 anxious 作表语;副词/名词均不可。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), '____ many varieties of English throughout the world.', 'It is', 'There are', 'They are', 'Here is', 'B', 'There be 存在句,主语 varieties 为复数,用 There are;It/They/Here is 都不合。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'The new word seemed ____ until I learned the culture behind it.', 'confusingly', 'confusion', 'confusing', 'confuse', 'C', 'seem 为系动词,后接形容词 confusing 作表语;副词/名词/动词不可。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'When the host said "Where?", the American became quite ____.', 'puzzle', 'puzzling him', 'puzzlingly', 'puzzled', 'D', 'become 为系动词,后接形容词 puzzled(感到困惑的)作表语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'In England, gravy is ____ and made from meat.', 'salty', 'saltily', 'salt', 'saltiness', 'A', 'be 后接形容词 salty 作表语;副词/名词均不可。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), '____ likely to be many differences even in the same language.', 'It is', 'There are', 'They have', 'Here are', 'B', 'There be 存在句,后跟 likely to be,表''存在……可能'';主语 differences 用 are。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'I felt ____ when a stranger said she liked my "pants".', 'embarrassingly', 'embarrass', 'embarrassed', 'embarrassment', 'C', 'feel 为系动词,后接形容词 embarrassed(感到尴尬的)作表语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'The differences are not mistakes; they are simply ____.', 'differently', 'difference', 'differ', 'different', 'D', 'are 为系动词,后接形容词 different 作表语;名词/副词/动词均不可。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'She was ____ that I had never tried French fries before.', 'amazed', 'amazingly', 'amaze', 'amazement', 'A', 'be 后接形容词 amazed(感到惊讶的)作表语;副词/动词/名词不可。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), '____ a kind of humble expression behind the Chinese words "Where? Where?".', 'It has', 'There is', 'They are', 'Here have', 'B', 'There be 存在句,主语 expression 单数用 There is。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'His explanation made everything ____ at last.', 'clearly', 'clearness', 'clear', 'clarify', 'C', '本题为宾补结构 make sth+形容词,clear 作宾语补足语;但形容词 vs 副词同样区分,clearly 不可。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'After living abroad for years, I have become much more ____ about time.', 'relaxedly', 'relax', 'relaxation', 'relaxed', 'D', 'become 为系动词,后接形容词 relaxed(轻松的)作表语;副词/动词/名词不可。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), '____ no single "right" meaning for the word "ahorita".', 'There is', 'It is', 'They are', 'Here is', 'A', 'There be 存在句表''不存在唯一含义'',主语 meaning 单数用 There is。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'The biscuits in America taste quite ____ rather than sweet.', 'savourily', 'savoury', 'savour', 'savouriness', 'B', 'taste 为系动词,后接形容词 savoury 作表语;副词/动词/名词不可。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), 'At first the strokes of the new language felt ____ on my tongue.', 'strangely', 'strangeness', 'strange', 'stranger ', 'C', 'feel 为系动词,后接形容词 strange 作表语;副词不能作表语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.02'), '____ always a reason why the same gesture means different things.', 'It is', 'They are', 'Here are', 'There is', 'D', 'There be 存在句,主语 reason 单数用 There is;It/They/Here 不合存在句。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'She gave ____ to show that she had to leave.', 'him a signal', 'a signal him', 'to him a signal', 'him to a signal', 'A', 'give sb sth 双宾结构,间接宾语 him 在前、直接宾语 a signal 在后。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'The cultural difference made the answer ____ to the American.', 'puzzle', 'puzzling', 'to puzzle', 'puzzlingly', 'B', 'make+宾语+宾补,形容词 puzzling 作宾语补足语;副词/动词原形不可。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'My friend asked me ____ I wanted to order French fries.', 'that', 'what about', 'whether', 'for', 'C', 'ask sb whether... 双宾+宾语从句;that 不引导''是否'',其余不合语法。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'Americans call ____ this purple vegetable on the menu.', '"eggplant" it', 'to it "eggplant"', 'for it "eggplant"', 'it "eggplant"', 'D', 'call sb/sth+名称,宾补结构,宾语 it 在前、补足语 "eggplant" 在后。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'The waiter brought ____ instead of the French fries I expected.', 'us a plate of chips', 'a plate of chips to we', 'to us a plate of chips', 'us a plate of chips to', 'A', 'bring sb sth 双宾,间接宾语 us 在前、直接宾语 a plate of chips 在后。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'What we call "biscuits", Americans ____ "cookies".', 'say', 'call', 'speak', 'tell', 'B', 'call sth+名称,宾补结构;say/speak/tell 不能接''宾语+名称''作宾补。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'The strange experience taught ____ about cultural differences.', 'a lot me', 'to me a lot', 'me a lot', 'for me a lot', 'C', 'teach sb sth 双宾,间接宾语 me 在前、直接宾语 a lot 在后。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'Living in Mexico has made my idea of time much more ____.', 'relax', 'to relax', 'relaxing it', 'relaxed', 'D', 'make+宾语 idea+宾补,形容词 relaxed 作宾语补足语;动词原形/不定式不可。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'A linguist once told ____ that "ahorita" could mean almost anything.', 'me a fact', 'a fact me', 'to me a fact', 'for me a fact', 'A', 'tell sb sth 双宾,间接宾语 me 在前、直接宾语 a fact 在后。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'The host''s reply "Where? Where?" left the visitor ____.', 'confuse', 'confused', 'to confuse', 'confusedly', 'B', 'leave+宾语+宾补,形容词 confused 作宾语补足语;副词/动词不可。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'She showed ____ how to read the menu in English.', 'a way me', 'to me a way', 'me a way', 'for a way me', 'C', 'show sb sth 双宾,间接宾语 me 在前、直接宾语 a way 在后。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'Everyone found the foreign word "ahorita" ____ at first.', 'confuse', 'to confuse', 'confusingly', 'confusing', 'D', 'find+宾语+宾补,形容词 confusing 作宾语补足语;动词/副词不可。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'The seller offered ____ as a polite way of saying "later".', 'me "ahorita"', '"ahorita" me to', 'to me "ahorita" for', 'for me "ahorita"', 'A', 'offer sb sth 双宾,间接宾语 me 在前、直接宾语 "ahorita" 在后。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'British people call ____, while Americans say "gas".', '"petrol" to it', 'it "petrol"', 'to it "petrol"', 'for "petrol" it', 'B', 'call sth+名称,宾补结构,宾语 it 在前、补足语 "petrol" 在后。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'Learning about culture gives ____ to communicate across countries.', 'confidence us', 'to us confidence', 'us confidence', 'for confidence us', 'C', 'give sb sth 双宾,间接宾语 us 在前、直接宾语 confidence 在后。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'The cross-cultural mix-up made both of them ____.', 'laughing', 'to laugh', 'laughed', 'laugh', 'D', 'make sb do,使役动词后接动词原形 laugh 作宾语补足语;-ing/不定式/过去式不可。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'My mum told ____ that "pants" meant trousers in America.', 'me the truth', 'the truth me', 'to me the truth', 'for me the truth', 'A', 'tell sb sth 双宾,间接宾语 me 在前、直接宾语 the truth 在后。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'We should keep our minds ____ when we meet a new culture.', 'openly', 'open', 'to open', 'opening it', 'B', 'keep+宾语 minds+宾补,形容词 open 作宾语补足语;副词/不定式不可。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'The kind seller passed ____ even though I had to leave.', 'the ice-cream me', 'to me the ice-cream', 'me the ice-cream', 'for me the ice-cream', 'C', 'pass sb sth 双宾,间接宾语 me 在前、直接宾语 the ice-cream 在后。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U2' AND code='s1u2.03'), 'Cultural knowledge makes communication ____ between different peoples.', 'easily', 'to ease', 'easing it', 'easier', 'D', 'make+宾语 communication+宾补,形容词 easier 作宾语补足语;副词/动词不可。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Word "Ahorita"', 'When a foreigner first set foot on Mexican soil, she learned a small but confusing word: "ahorita". She asked an ice-cream seller for an ice-cream, and he answered "ahorita". Because the word can be directly translated as "right now", she thought the ice-cream would come at once. But she waited for half an hour, and still nothing came. When she asked again, the seller said "ahorita" once more, with a face full of confusion. Years later, back in Mexico, she finally understood that the word should almost never be taken literally. Its meaning changes greatly with the context. It could mean tomorrow, in an hour, within five years, or even never. It is even used as a polite way of saying "no, thanks". Understanding "ahorita" took not a fluency in the language, but a fluency in the culture behind it.', 'Language and Culture', 140, '[{"q":"Why did the foreigner keep waiting after the seller said \"ahorita\"?","answer":"A","options":["She believed it meant \"right now\".","She had paid too much money.","She could not speak any Spanish.","She wanted to test the seller."],"explanation":"原文 ''directly translated as \"right now\"… thought the ice-cream would come at once'' 的转述。"},{"q":"What does the passage say about the meaning of \"ahorita\"?","answer":"B","options":["It always means \"in five minutes\".","It depends a lot on the situation.","It has no real meaning at all.","It is only used by children."],"explanation":"原文 ''meaning changes greatly with the context'' 的转述。"},{"q":"What did the foreigner finally realise about understanding the word?","answer":"A","options":["It required knowing the culture, not just the language.","It needed perfect Spanish grammar.","It was impossible for any foreigner.","It could be learned from a dictionary."],"explanation":"末句 ''took not a fluency in the language, but a fluency in the culture'' 的转述。"}]'::jsonb, '[{"word":"literally","cn":"照字面地"},{"word":"context","cn":"语境"},{"word":"fluency","cn":"流利;熟悉"}]'::jsonb, 2, 'required1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Two Kinds of English', 'A British child once travelled across the United States and noticed something funny about the way people spoke English. At a restaurant, a friend asked her to order "French fries". She had no idea what they were, until the waiter brought a plate of chips. Later the friend said she would buy some "chips", but came back with a packet of crisps! During the holiday they were offered "biscuits and gravy". In England biscuits are sweet, so this sounded very strange. The child later realised that "biscuits" in America are savoury snacks, and what the British call "biscuits", Americans call "cookies". She was even embarrassed when a stranger said she liked her "pants", because in British English that word means underwear. Although the same language is spoken in both countries, there are likely to be many differences, not just in vocabulary but also in spelling, grammar and pronunciation.', 'Language and Culture', 148, '[{"q":"What did the waiter actually bring when the child ordered \"French fries\"?","answer":"B","options":["A bowl of soup.","A plate of chips.","A packet of crisps.","Some sweet biscuits."],"explanation":"原文 ''the waiter brought a plate of chips''。"},{"q":"Why was the child embarrassed by the word \"pants\"?","answer":"C","options":["She had forgotten to wear them.","She did not own any.","In British English it means underwear.","It was too expensive to buy."],"explanation":"原文 ''in British English that word means underwear'' 的转述。"},{"q":"What is the main point of the passage?","answer":"D","options":["American food is better than British food.","Children should not travel abroad.","Restaurants often make mistakes.","The same language can differ in many ways between countries."],"explanation":"末句 ''there are likely to be many differences, not just in vocabulary…'' 的转述。"}]'::jsonb, '[{"word":"savoury","cn":"咸味的"},{"word":"vocabulary","cn":"词汇"},{"word":"pronunciation","cn":"发音"}]'::jsonb, 2, 'required1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'When a Gesture Means "No"', 'Using gestures to show what you feel is common in some countries but not in others. Most people think that shaking the head means "no", but this is not true everywhere. In a few countries, the same gesture can carry the opposite meaning. For example, in some areas people tip their head from side to side to say "yes", which often surprises visitors. A traveller who nods or shakes without thinking may send the wrong message and cause a small misunderstanding. The lesson is simple: a gesture is a kind of language, and like words, it does not mean the same thing in every culture. Before you travel, it is a good idea to learn how local people use their hands and heads. A friendly smile, however, seems to mean the same warm thing almost everywhere, which is why it is often called a universal gesture.', 'Language and Culture', 146, '[{"q":"What does the passage say about shaking the head?","answer":"A","options":["In some places it can mean the opposite.","It always means \"no\" everywhere.","It is never used by travellers.","It is the same as a smile."],"explanation":"原文 ''the same gesture can carry the opposite meaning'' 的转述。"},{"q":"Why might a traveller cause a misunderstanding?","answer":"B","options":["By speaking too quietly.","By using a gesture that means something different locally.","By eating the wrong food.","By arriving too early."],"explanation":"原文 ''may send the wrong message and cause a small misunderstanding'' 的转述。"},{"q":"What does the writer suggest about a smile?","answer":"C","options":["It is rude in most countries.","It should be avoided abroad.","Its friendly meaning is shared in almost every culture.","It can only be understood at home."],"explanation":"末句 ''a friendly smile… seems to mean the same warm thing almost everywhere'' 的转述。"}]'::jsonb, '[{"word":"gesture","cn":"手势"},{"word":"opposite","cn":"相反的"},{"word":"universal","cn":"通用的"}]'::jsonb, 2, 'required1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Many Meanings of "Chi"', 'A simple Chinese word, "chi", which means "to eat", has a lot of extended meanings that may surprise a learner. As the saying goes, people cannot do without food, and the Chinese love of food has given many colourful expressions to the language. Sometimes the word goes far beyond its literal meaning. For example, "chi cu" sounds like "to eat vinegar", but it really means to be jealous. "Chi moshui" sounds like "to eat ink", yet it means to receive education. The word can even mean "to depend on": "kaoshan chishan" means that people living near a mountain make a living from the mountain. So when foreign students meet "chi", they should not always take it literally. Behind such a small word lies a whole way of thinking, and learning these expressions helps students understand Chinese culture as well as the language.', 'Language and Culture', 142, '[{"q":"What does \"chi cu\" really mean?","answer":"D","options":["To eat real vinegar.","To receive education.","To climb a mountain.","To be jealous."],"explanation":"原文 ''\"chi cu\"… really means to be jealous''。"},{"q":"What does \"chi moshui\" actually refer to?","answer":"A","options":["Getting an education.","Drinking dark water.","Feeling hungry.","Making a living."],"explanation":"原文 ''\"chi moshui\"… means to receive education'' 的转述。"},{"q":"According to the passage, why is learning these expressions useful?","answer":"B","options":["Because they make food taste better.","Because they help learners understand the culture too.","Because they are easy to spell.","Because they are only used in exams."],"explanation":"末句 ''learning these expressions helps students understand Chinese culture as well as the language'' 的转述。"}]'::jsonb, '[{"word":"extended","cn":"引申的"},{"word":"jealous","cn":"嫉妒的"},{"word":"literally","cn":"照字面地"}]'::jsonb, 2, 'required1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'What Colours Say', 'Colours carry different cultural messages in different parts of the world, and this can lead to surprising mistakes. In many Western countries, a bride wears white at her wedding because white stands for purity and a new start. In some Asian cultures, however, white has long been linked with sadness and is worn at funerals instead. Red is another good example. In China, red is the colour of luck and happiness, so people use it at weddings and during the Spring Festival. In a few Western countries, red can warn of danger or anger. Black, too, is read in different ways: it may mean sad in one place but smart and formal in another. These meanings are not fixed; they have changed over time and may keep changing. So a colour is never just a colour. Knowing what a colour means in another culture can help us avoid sending the wrong message.', 'Language and Culture', 152, '[{"q":"Why do brides in many Western countries wear white?","answer":"C","options":["White is the cheapest colour.","White means danger to them.","To them, it suggests being pure and making a fresh start.","White is worn only at funerals."],"explanation":"原文 ''white stands for purity and a new start'' 的转述。"},{"q":"How is the colour red seen in China, according to the text?","answer":"D","options":["As a sign of sadness.","As a warning of danger.","As a formal business colour.","As a sign of good luck and joy."],"explanation":"原文 ''In China, red is the colour of luck and happiness'' 的转述。"},{"q":"What does the writer say about the meanings of colours?","answer":"A","options":["They differ by culture and can change over time.","They are exactly the same everywhere.","They never change at all.","They are decided by the government."],"explanation":"原文 ''These meanings are not fixed; they have changed over time'' 的转述。"}]'::jsonb, '[{"word":"purity","cn":"纯洁"},{"word":"funeral","cn":"葬礼"},{"word":"formal","cn":"正式的"}]'::jsonb, 2, 'required1', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Learning the Culture, Not Just the Words', 'Many students believe that learning a language is only about memorising words and grammar, but real understanding asks for more. A Chinese learner of English may know every word in a polite request, yet still feel unsure whether to say "Open the window" or "Would you mind opening the window?". The right choice depends on who you are talking to and where you are. In the same way, a foreigner studying Chinese may be confused when a host smiles and says "Where? Where?" after a compliment, because the words are humble rather than a real question. These small moments show that language and culture cannot be separated. When we learn how people use a language in real life, we make fewer mistakes and feel more confident. That is why many teachers say the most exciting part of learning a language is discovering the culture hidden inside it.', 'Language and Culture', 147, '[{"q":"According to the passage, what decides which polite form to use?","answer":"B","options":["The number of words you know.","The person and the situation you are in.","The time of the day.","The price of the lesson."],"explanation":"原文 ''depends on who you are talking to and where you are'' 的转述。"},{"q":"Why might a foreigner be confused by \"Where? Where?\"?","answer":"C","options":["The host is asking for directions.","The host is angry at the compliment.","The words are humble, not a real question.","The words have no meaning at all."],"explanation":"原文 ''the words are humble rather than a real question'' 的转述。"},{"q":"What is the main message of the passage?","answer":"D","options":["Grammar is the only important thing.","Foreigners should not learn Chinese.","Teachers dislike teaching culture.","Language and culture should be learned together."],"explanation":"原文 ''language and culture cannot be separated'' 的转述。"}]'::jsonb, '[{"word":"request","cn":"请求"},{"word":"compliment","cn":"赞美"},{"word":"separate","cn":"分开"}]'::jsonb, 2, 'required1', 'U2', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'A Funny Meal Abroad', 'On my first trip to America, a small word almost spoiled my lunch. My friend asked me whether I wanted to (1)____ some "French fries". I had no (2)____ what they were, so I just smiled. When the waiter came, he put a (3)____ of hot chips in front of me. I was (4)____ to learn that "fries" and "chips" were the same food. Later we were given "biscuits", but they did not (5)____ sweet at all; they were salty and soft. My friend (6)____ that in America "biscuits" are savoury snacks. I felt a little (7)____ about all my mistakes, but she told me it was not my (8)____. The same (9)____ is spoken in our two countries, yet the words can be quite different. By the end of the meal, we were both (10)____ at how funny language can be.', 142, 2, '[{"q":"1","answer":"A","options":["order","throw","sell","lose"],"explanation":"order food 点餐。"},{"q":"2","answer":"B","options":["money","idea","time","friend"],"explanation":"have no idea 不知道。"},{"q":"3","answer":"C","options":["book","box","plate","song"],"explanation":"a plate of chips 一盘薯条。"},{"q":"4","answer":"D","options":["angry","sad","bored","amazed"],"explanation":"amazed to learn 惊讶地得知。"},{"q":"5","answer":"A","options":["taste","look","sound","feel"],"explanation":"taste sweet 尝起来甜(系动词)。"},{"q":"6","answer":"B","options":["asked","explained","hoped","wished"],"explanation":"explained that 解释说。"},{"q":"7","answer":"C","options":["proud","happy","embarrassed","calm"],"explanation":"feel embarrassed 感到尴尬。"},{"q":"8","answer":"D","options":["price","noise","city","fault"],"explanation":"not my fault 不是我的错。"},{"q":"9","answer":"A","options":["language","machine","garden","market"],"explanation":"the same language 同一种语言。"},{"q":"10","answer":"B","options":["crying","laughing","sleeping","leaving"],"explanation":"laughing at how funny 笑语言多有趣。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'The Story of One Word', 'My Chinese teacher loves to tell us the (1)____ behind a single word. One day she taught us "chi", which simply (2)____ "to eat". But she said the word often goes far beyond its (3)____ meaning. For example, "chi cu" sounds like eating vinegar, but it really (4)____ to be jealous. We were all (5)____ to hear that. She also told us that "chi moshui" does not mean eating ink; it (6)____ to receiving an education. I learned that we should not always take a word (7)____. Behind such a small word (8)____ a whole way of thinking. Now, whenever I meet a new Chinese word, I try to find the (9)____ hidden inside it. Learning these expressions has made the (10)____ much more interesting to me.', 127, 2, '[{"q":"1","answer":"C","options":["price","noise","story","weather"],"explanation":"the story behind 背后的故事。"},{"q":"2","answer":"D","options":["sells","buys","loses","means"],"explanation":"means \"to eat\" 意为。"},{"q":"3","answer":"A","options":["literal","high","cheap","loud"],"explanation":"literal meaning 字面意思。"},{"q":"4","answer":"B","options":["forgets","means","leaves","sells"],"explanation":"means to be jealous 意为嫉妒。"},{"q":"5","answer":"C","options":["bored","angry","amazed","afraid"],"explanation":"amazed to hear 惊讶地听到。"},{"q":"6","answer":"D","options":["sells","throws","hides","refers"],"explanation":"refers to 指的是。"},{"q":"7","answer":"A","options":["literally","slowly","quietly","loudly"],"explanation":"take a word literally 按字面理解。"},{"q":"8","answer":"B","options":["sells","lies","buys","loses"],"explanation":"behind … lies … 在……背后有(倒装)。"},{"q":"9","answer":"C","options":["price","noise","meaning","ticket"],"explanation":"the meaning hidden inside 隐藏的含义。"},{"q":"10","answer":"D","options":["weather","market","machine","language"],"explanation":"made the language interesting 让语言有趣。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'A Lesson on Gestures', 'Today our teacher gave us a fun (1)____ on body language. She said that a gesture is a kind of (2)____, just like words. Most of us think that shaking the head always (3)____ "no", but she told us this is not true everywhere. In some places, the same gesture can carry the (4)____ meaning. A careless traveller may send the (5)____ message and cause a small misunderstanding. So before you visit a new country, it is (6)____ to learn how local people use their hands. The teacher also said that a friendly (7)____ seems to mean the same warm thing almost everywhere. We were all (8)____ by how much a single movement can say. After the (9)____, I felt that learning gestures is part of learning a (10)____.', 129, 2, '[{"q":"1","answer":"A","options":["lesson","price","noise","garden"],"explanation":"a fun lesson 有趣的一课。"},{"q":"2","answer":"B","options":["machine","language","market","ticket"],"explanation":"a kind of language 一种语言。"},{"q":"3","answer":"C","options":["sells","loses","means","buys"],"explanation":"means \"no\" 意为''不''。"},{"q":"4","answer":"D","options":["same","cheap","loud","opposite"],"explanation":"the opposite meaning 相反的意思。"},{"q":"5","answer":"A","options":["wrong","right","happy","quiet"],"explanation":"the wrong message 错误的信息。"},{"q":"6","answer":"B","options":["lucky","wise","rude","late"],"explanation":"it is wise to 明智的做法。"},{"q":"7","answer":"C","options":["price","noise","smile","machine"],"explanation":"a friendly smile 友好的微笑。"},{"q":"8","answer":"D","options":["bored","angry","tired","amazed"],"explanation":"amazed by 被……惊到。"},{"q":"9","answer":"A","options":["lesson","market","garden","machine"],"explanation":"after the lesson 课后。"},{"q":"10","answer":"B","options":["machine","culture","garden","market"],"explanation":"learning a culture 学习一种文化。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'A New Sense of Time', 'After I moved to a small town abroad, my (1)____ towards time slowly changed. At home, I used to (2)____ if I was even five minutes late. People around me, however, were much more (3)____ about the clock. When a shop owner said he would help me "soon", he did not (4)____ it literally; "soon" could mean in an hour or even the next day. At first this made me (5)____, because I expected things to happen at once. But over the months my (6)____ towards being late changed a lot. I am still (7)____ on time for important appointments, but when I am a little late, I no longer (8)____. Living here has taught (9)____ a new way to look at time. Ironically, I now feel that I live more in the (10)____ moment than ever before.', 138, 2, '[{"q":"1","answer":"C","options":["price","garden","attitude","machine"],"explanation":"attitude towards time 对时间的态度。"},{"q":"2","answer":"D","options":["sell","sleep","sing","panic"],"explanation":"panic if late 迟到就慌。"},{"q":"3","answer":"A","options":["relaxed","angry","afraid","sorry"],"explanation":"relaxed about the clock 对时间放松。"},{"q":"4","answer":"B","options":["sell","mean","hide","lose"],"explanation":"mean it literally 按字面意思理解。"},{"q":"5","answer":"C","options":["happy","proud","anxious","quiet"],"explanation":"made me anxious 让我焦虑(系动词后形容词)。"},{"q":"6","answer":"D","options":["price","noise","ticket","attitude"],"explanation":"my attitude 我的态度。"},{"q":"7","answer":"A","options":["usually","late","free","never"],"explanation":"usually on time 通常准时。"},{"q":"8","answer":"B","options":["sell","panic","sing","hide"],"explanation":"no longer panic 不再惊慌。"},{"q":"9","answer":"C","options":["we","they","me","he"],"explanation":"taught me 教会了我(间接宾语)。"},{"q":"10","answer":"D","options":["past","future","ancient","present"],"explanation":"the present moment 当下时刻。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'Word Cards for Two Englishes', 'To remember the differences between British and American English, I made some word (1)____. On each card I wrote a British word on one side and the American word on the (2)____. For example, the British say "petrol" while Americans (3)____ "gas". A British "flat" is an American "apartment", and a British "biscuit" is an American "cookie". These are not (4)____; they are just two ways of speaking the same language. At first the differences (5)____ me, but the cards helped a lot. Now, whenever I am not (6)____ which word someone means, I simply ask in a (7)____ way. My English teacher was (8)____ that I had made so many cards by myself. She said that paying attention to such (9)____ would make me a better speaker. Step by step, I have grown more (10)____ when I talk with people from different countries.', 144, 2, '[{"q":"1","answer":"A","options":["cards","prices","noises","machines"],"explanation":"word cards 单词卡片。"},{"q":"2","answer":"B","options":["sky","other","wall","floor"],"explanation":"on the other (side) 另一面。"},{"q":"3","answer":"C","options":["sell","buy","say","lose"],"explanation":"Americans say \"gas\" 美国人说。"},{"q":"4","answer":"D","options":["songs","prices","games","mistakes"],"explanation":"not mistakes 不是错误。"},{"q":"5","answer":"A","options":["confused","helped","saved","praised"],"explanation":"confused me 让我困惑。"},{"q":"6","answer":"B","options":["late","sure","free","busy"],"explanation":"not sure 不确定。"},{"q":"7","answer":"C","options":["loud","rude","polite","quick"],"explanation":"in a polite way 礼貌地。"},{"q":"8","answer":"D","options":["angry","bored","sorry","amazed"],"explanation":"amazed that 惊讶于。"},{"q":"9","answer":"A","options":["differences","prices","noises","tickets"],"explanation":"such differences 这些差异。"},{"q":"10","answer":"B","options":["afraid","confident","tired","bored"],"explanation":"more confident 更自信。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'Where Greetings Come From', 'Many everyday greetings have a surprising (1)____. Take the Italian word "ciao", which people now use to (2)____ hello or goodbye. Long ago, it came from a phrase whose literal (3)____ was "I am your slave". Of course, no one (4)____ it that way today; its real meaning is friendly and warm. The English word "hello" also has an interesting (5)____. It is said to come from an old French word that roughly (6)____ "whoa there!". Over time the word slowly (7)____ into the friendly greeting we know now. These small facts show that words can (8)____ greatly over the years. When we learn where a greeting comes from, we understand the (9)____ behind it a little better. For me, this is the most (10)____ part of studying a language.', 130, 2, '[{"q":"1","answer":"C","options":["price","noise","origin","garden"],"explanation":"a surprising origin 令人惊讶的由来。"},{"q":"2","answer":"D","options":["sell","buy","lose","mean"],"explanation":"mean hello 表示你好。"},{"q":"3","answer":"A","options":["translation","price","weather","ticket"],"explanation":"literal translation 字面译文。"},{"q":"4","answer":"B","options":["sells","takes","buys","hides"],"explanation":"takes it that way 那样理解。"},{"q":"5","answer":"C","options":["price","noise","history","machine"],"explanation":"an interesting history 有趣的来历。"},{"q":"6","answer":"D","options":["sells","buys","loses","means"],"explanation":"roughly means 大致意思是。"},{"q":"7","answer":"A","options":["grew","sold","lost","broke"],"explanation":"grew into 逐渐变成。"},{"q":"8","answer":"B","options":["sell","change","buy","hide"],"explanation":"change greatly 变化很大。"},{"q":"9","answer":"C","options":["price","noise","culture","machine"],"explanation":"the culture behind it 背后的文化。"},{"q":"10","answer":"D","options":["boring","expensive","quiet","exciting"],"explanation":"the most exciting part 最激动人心的部分。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 Ordering Food in America', '上外必修一 U2 · dialogue', 3, 'Lily: Do you want to order some French fries with me?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 Gestures Around the World', '上外必修一 U2 · passage', 2, 'Using gestures to show feelings is common in some countries but not in others.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 What Do You Mean by "Pants"?', '上外必修一 U2 · dialogue', 3, 'Anna: I really need to buy some new pants this weekend.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 The Word "Chi"', '上外必修一 U2 · passage', 2, 'The simple Chinese word "chi" means "to eat".
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 A New Sense of Time', '上外必修一 U2 · dialogue', 3, 'Mia: You''ve lived in Mexico for years. Has anything about you changed?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 Where "Ciao" Comes From', '上外必修一 U2 · passage', 2, 'Many friendly greetings have a surprising history.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Introducing a Chinese Word and the Culture Behind It(介绍一个汉语词及其背后的文化)', 'A Chinese Word and Its Story', '假设来自姐妹学校的外国学生正在参观你校,你被邀请做一个关于"汉语词及其故事"的小演讲。请用英语写一篇约80词的短文,介绍一个汉语词(如"吃 chi"),内容包括:① 一个清楚的主题句(这个词有很多引申含义);② 两三个例子说明它超出字面意思;③ 简述这个词背后的文化。注意:所有支撑句都要围绕主题句,代词指代清楚。', 'Suppose some students from your sister school abroad are visiting your school, and you are asked to give a short talk about "Chinese words and their stories". Write a short passage (about 80 words) to introduce one Chinese word (e.g. "chi"). Include: 1) a clear topic sentence (the word has many extended meanings); 2) two or three examples showing it goes beyond its literal meaning; 3) a brief note on the culture behind the word. Make sure every supporting sentence relates to the topic sentence and your pronouns are clear.', '["主题句(A simple Chinese word \"chi\" has a lot of extended meanings.)","例子说明超出字面(\"chi cu\" really means … rather than to eat vinegar.)","背后的文化(Behind the word lies the Chinese love of food.)","所有支撑句围绕主题、代词指代清楚"]'::jsonb, 70, 100, 'Hello, everyone! Today I''d like to share a simple Chinese word, "chi", which means "to eat" but has many extended meanings. The word often goes far beyond its literal meaning. For example, "chi cu" really means to be jealous rather than to eat vinegar, and "chi moshui" means to receive an education rather than to eat ink. Behind these expressions lies the Chinese love of food, which has given the language many colourful sayings. So a small word like "chi" can open a window onto our culture. Thank you for listening!', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["A simple Chinese word \"chi\" has a lot of extended meanings.","The word often goes far beyond its literal meaning.","\"Chi cu\" really means to be jealous rather than to eat vinegar.","Behind these expressions lies the Chinese love of food."]'::jsonb, '[{"wrong":"The word has many meaning.","correct":"The word has many meanings.","note":"many 后接可数名词复数 meanings。"},{"wrong":"It means to be jealous literal.","correct":"It means to be jealous literally.","note":"修饰动词要用副词 literally,不用形容词 literal。"},{"wrong":"Behind these expressions lie the Chinese love of food.","correct":"Behind these expressions lies the Chinese love of food.","note":"倒装句主语 the love 为单数,谓语用 lies。"}]'::jsonb, '【介绍汉语词结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required1', 'U2', '{"title":"英语基本句型(Basic Sentence Patterns)速查","intro":"英语句子万变不离五种基本句型。先找主干(主语+谓语),再看谓语动词后面缺什么:不缺=主谓;缺一个宾语=主谓宾;缺表语=主系表;给某人某物=双宾;宾语后还要补充说明=宾补。","table":{"headers":["句型","结构 / 例句"],"rows":[["主谓 SV","主语+不及物动词:The meaning changes greatly."],["主谓宾 SVO","主语+及物动词+宾语:I spoke Spanish well."],["主系表 SVC","主语+系动词+表语(形容词/名词):I was torn. / It sounds strange."],["主谓双宾 SVOO","主语+动词+间宾+直宾:She gave him a signal."],["主谓宾补 SVOC","主语+动词+宾语+宾补:She found the word confusing. / They call it \"eggplant\"."]]},"specialRules":[{"rule":"系动词(be/look/feel/become/sound/taste/seem/get)后用形容词作表语,不用副词","mark":"feel strange √ / feel strangely ×"},{"rule":"及物动词后必须带宾语,不及物动词后不带(或加介词)","mark":"differ from √ / differ sth ×"},{"rule":"双宾语序:间接宾语(人)在前、直接宾语(物)在后;或用 to/for 改写","mark":"give him a signal = give a signal to him"},{"rule":"There be 表''存在/有'',be 与后面的真正主语保持数一致","mark":"There are many varieties / There is a reason"},{"rule":"make/let/have/使役 + 宾语 + 动词原形作宾补","mark":"made both of them laugh(不加 to)"}],"why":["找句型的关键是先抓主干、再看谓语动词:它是否需要宾语、是否是系动词、是否要补足语。判断对了句型,理解长难句就不会乱。"],"gaokaoPoints":["系动词后形容词 vs 副词(语法填空/改错高频):He felt nervous,不是 nervously。","双宾与宾补的辨认:give sb sth 与 make sb sth(后者是宾语+补足语,语义不同)。","There be 句型的主谓一致与时态:There seems to be / There are likely to be。"],"examVsReal":[{"exam":"She gave him a signal.（考试标准双宾）","real":"She gave a signal to him.","note":"考试两种都对;口语里强调''给谁''时常用 to him 的改写式"},{"exam":"I felt embarrassed.（系表·形容词）","real":"I was so embarrassed!","note":"意思相同;真实口语爱加 so/really 等程度词,但系动词后仍是形容词"}]}'::jsonb, 'sufe');
